window.ScripturaLexicons.BDAG_PART_0207 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-01\" data-source=\"BDAG\" data-search=\"κομάω verbo ter cabelos compridos; deixar crescer os cabelos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κομάω</td><td>verbo</td><td>ter cabelos compridos; deixar crescer os cabelos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-02\" data-source=\"BDAG\" data-search=\"κόμη, ης, ἡ substantivo feminino cabeleira; cabelos da cabeça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόμη, ης, ἡ</td><td>substantivo feminino</td><td>cabeleira; cabelos da cabeça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-03\" data-source=\"BDAG\" data-search=\"κομίζω verbo levar; trazer; recuperar; receber recompensa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κομίζω</td><td>verbo</td><td>levar; trazer; recuperar; receber recompensa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-04\" data-source=\"BDAG\" data-search=\"κόμπος, ου, ὁ substantivo masculino vanglória; jactância; ostentação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόμπος, ου, ὁ</td><td>substantivo masculino</td><td>vanglória; jactância; ostentação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-05\" data-source=\"BDAG\" data-search=\"κομφέκτωρ, ορος, ὁ substantivo masculino executor; carrasco; encarregado do golpe de misericórdia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κομφέκτωρ, ορος, ὁ</td><td>substantivo masculino</td><td>executor; carrasco; encarregado do golpe de misericórdia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-06\" data-source=\"BDAG\" data-search=\"κομψότερον advérbio comparativo melhor; em melhor estado de saúde BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κομψότερον</td><td>advérbio comparativo</td><td>melhor; em melhor estado de saúde</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-07\" data-source=\"BDAG\" data-search=\"κονιάω verbo caiar; revestir de cal; branquear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κονιάω</td><td>verbo</td><td>caiar; revestir de cal; branquear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-08\" data-source=\"BDAG\" data-search=\"κονιορτός, οῦ, ὁ substantivo masculino poeira; pó levantado; nuvem de poeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κονιορτός, οῦ, ὁ</td><td>substantivo masculino</td><td>poeira; pó levantado; nuvem de poeira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-09\" data-source=\"BDAG\" data-search=\"κοπάζω verbo diminuir; cessar; amainar; acalmar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοπάζω</td><td>verbo</td><td>diminuir; cessar; amainar; acalmar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-10\" data-source=\"BDAG\" data-search=\"κοπετός, οῦ, ὁ substantivo masculino pranto; lamento; lamentação fúnebre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοπετός, οῦ, ὁ</td><td>substantivo masculino</td><td>pranto; lamento; lamentação fúnebre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-11\" data-source=\"BDAG\" data-search=\"κοπή, ῆς, ἡ substantivo feminino golpe; massacre; derrota BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοπή, ῆς, ἡ</td><td>substantivo feminino</td><td>golpe; massacre; derrota</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-12\" data-source=\"BDAG\" data-search=\"κοπιάω verbo cansar-se; fatigar-se; trabalhar arduamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοπιάω</td><td>verbo</td><td>cansar-se; fatigar-se; trabalhar arduamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-13\" data-source=\"BDAG\" data-search=\"κόπος, ου, ὁ substantivo masculino dificuldade; incômodo; trabalho árduo; fadiga BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόπος, ου, ὁ</td><td>substantivo masculino</td><td>dificuldade; incômodo; trabalho árduo; fadiga</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-14\" data-source=\"BDAG\" data-search=\"κοπρία, ας, ἡ substantivo feminino esterqueira; monte de estrume BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοπρία, ας, ἡ</td><td>substantivo feminino</td><td>esterqueira; monte de estrume</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-15\" data-source=\"BDAG\" data-search=\"κόπριον, ου, τό substantivo neutro esterco; estrume; imundície; sujeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόπριον, ου, τό</td><td>substantivo neutro</td><td>esterco; estrume; imundície; sujeira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-16\" data-source=\"BDAG\" data-search=\"κόπρον, ου, τό substantivo neutro esterco; estrume (forma de gênero incerto) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόπρον, ου, τό</td><td>substantivo neutro</td><td>esterco; estrume (forma de gênero incerto)</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-17\" data-source=\"BDAG\" data-search=\"κόπρος, ου, ἡ substantivo feminino esterco; estrume BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόπρος, ου, ἡ</td><td>substantivo feminino</td><td>esterco; estrume</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-18\" data-source=\"BDAG\" data-search=\"κόπτω verbo cortar; abater; bater no peito; lamentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόπτω</td><td>verbo</td><td>cortar; abater; bater no peito; lamentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-19\" data-source=\"BDAG\" data-search=\"κόραξ, ακος, ὁ substantivo masculino corvo; gralha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόραξ, ακος, ὁ</td><td>substantivo masculino</td><td>corvo; gralha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0207-20\" data-source=\"BDAG\" data-search=\"κοράσιον, ου, τό substantivo neutro menina; jovem garota BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοράσιον, ου, τό</td><td>substantivo neutro</td><td>menina; jovem garota</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0207-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κομάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κομάω</span> (veja <span class=\"greek\">κόμη</span>; compare o latim comans; desde Hom. e outros; BGU 16, 11; Philo, Deus Imm. 88, Spec. Leg. 3, 37; Jos., Ant. 4, 72): usar cabelos compridos, deixar os cabelos crescerem (Diod S 20, 63, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:14</a>, 15 (Paulo argumenta com base na natureza, mas tem a seu favor o costume romano; os autores antigos não são unânimes quanto ao costume grego: veja Il. 2, 11 e outras passagens, ‘aqueus de longos cabelos’; Hdt. 1, 82, 7, a respeito de um voto; Aristot., Rhet. 1367a, 26, cabelo comprido como sinal de nobreza na Lacedemônia; Plut., Mor. 267b, os gregos normalmente não usam cabelos compridos; Ps.-Phoc. 212 <span class=\"greek\">ἄρσεσιν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπέοικε</span> <span class=\"greek\">κομᾶν</span>, não convém aos homens usar cabelos compridos; JMurphy-OConnor, CBQ 42, ’80, 484–87: para alguns, indício de efeminação; compare Juvenal 2, 96. Sobre uma perspectiva israelita, veja Judg 16:19; compare Philo, Spec. Leg. 3, 37; Billerb. III 441f; CGordon, Homer and Bible: HUCA 26, ’55, 84f. Outras referências: PvanderHorst, The Sentences of Pseudo-Phocylides ’78, 249f. Talvez Paulo se refira ao modo efeminado com que certos homens penteavam os cabelos compridos, em vez de se referir simplesmente ao uso do cabelo em seu comprimento natural.)—MAndronicos e outros, The Gk. Museum ’75 (ilustrações); RAC IV 629f. DELG s.v. <span class=\"greek\">κόμη</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόμη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόμη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (veja o verbete precedente; Hom. e outros; WSchubart, Der Gnomon des Idios Logos1919 [=BGU V], 71; 76 [II d.C.]: <span class=\"greek\">ἱερεῦσι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐξὸν</span> <span class=\"greek\">κόμην</span> <span class=\"greek\">φορεῖν</span>, não é permitido aos sacerdotes usar cabeleira comprida; LXX; Philo, Sacr. Abel. 25; Jos., Bell. 4, 561, Ant. 14, 45; Tat. 25, 1; empréstimo no hebraico rabínico): cabelos da cabeça de uma pessoa, cabelos (compridos) das mulheres (Xenophon Eph. 1, 2, 6; Achilles Tat. 8, 6, 8; os contextos dessas referências sugerem que os cabelos das personagens femininas eram compridos), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:15</a>; aqui, cabelos sem referência especial ao comprimento, questão abordada na oração precedente. Mulheres de boa educação mantinham suas madeixas presas no alto da cabeça. <span class=\"greek\">κ</span>. <span class=\"greek\">οὔλη</span>, cabelos encaracolados, ApcPt 3:10.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κομίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κομίζω</span>: 1º aoristo <span class=\"greek\">ἐκόμισα</span>. Na voz média: futuro <span class=\"greek\">κομίσομαι</span> e <span class=\"greek\">κομιοῦμαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:25</a>, variante de leitura; 1º aoristo <span class=\"greek\">ἐκομισάμην</span>; perfeito <span class=\"greek\">κεκόμισμαι</span>. Na passiva: aoristo, 3ª pessoa do singular, <span class=\"greek\">ἐκομίσθη</span>, 1 Esdr 2:14 (<span class=\"greek\">κομέω</span>, ‘cuidar de’; desde Hom.).</p>\n<p class=\"entry-text\">① Transportar alguma coisa até um destino específico, levar, trazer, na ativa (SIG 409, 29; 434, 42; 559, 28; PPetr III, 53k, 5; PTebt 55, 4; 1 Esdr 4:5; 3 Macc 1:8); com <span class=\"greek\">τὶ</span>, alguma coisa (Jos., Vi. 50 <span class=\"greek\">ἐπιστολάς</span>, cartas; TestJos 6:2): um frasco de unguento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:37</a>.</p>\n<p class=\"entry-text\">② Receber de volta algo que pertence à pessoa ou lhe é devido; recuperar, reaver, na voz média (Eur., Thu. e outros; Isaeus 8, 8; Polyb. 1, 83, 8; 3, 40, 10; 10, 34, 3; Sir 29:6; Philo, De Jos. 210; 231; Jos., Ant. 13, 80): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐμὸν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τόκῳ</span>, o que é meu com juros (sobre o uso comercial, compare Lys. 32, 14; Andoc. 1, 38), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:27</a>. Sobre Abraão: receber (o filho) de volta (compare Jos., Ant. 1, 236; Isaeus 8:8, de uma filha), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:19</a> (Himerius, Or. 6 [2], Deméter <span class=\"greek\">τὴν</span> <span class=\"greek\">ζητουμένην</span> <span class=\"greek\">κομίζεται</span> = recebe a mulher que procurava [sua filha]).</p>\n<p class=\"entry-text\">③ Entrar na posse de alguma coisa ou experimentar algo; obter para si, receber, frequentemente como recompensa, na voz média (Diod S 17, 69, 1; 20, 28, 3; Appian, Bell. Civ. 5, 60, §252 <span class=\"greek\">γράμματα</span>, cartas): <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀψώνια</span>, pagamento, soldo, IPol 6:2; <span class=\"greek\">μισθόν</span>, remuneração (Polystrat. p. 22; Lucian, Phal. 2, 5; SIG 193, 9; 11; 1077, 4; 2 Macc 8:33; Ath., R. 18 p. 70, 30 <span class=\"greek\">κομίσασθαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπίχειρα</span>), 2 Cl 11:5; compare B 4:12, onde se deve suprir <span class=\"greek\">μισθόν</span> (como em En 100:7). <span class=\"greek\">μισθὸν</span> <span class=\"greek\">ἀδικίας</span>, pagamento pela injustiça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:13</a>, variante de leitura (veja <span class=\"greek\">ἀδικέω</span> 2, final). De um favor divino especial concedido em reconhecimento da piedade (Diod S 3, 2, 4): <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">στέφανον</span>, a coroa de glória, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:4</a> (compare Eur., Hipp. 432 codd. <span class=\"greek\">κ</span>. <span class=\"greek\">δόξαν</span>; 1 Macc 13:37). <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἔπραξεν</span>, receber a retribuição por aquilo que (cada um) fez durante a vida no corpo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:10</a> (compare as cenas de julgamento em Pla., Phd. 113 e 114; veja também Diod S 8, 15); compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:25</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">κομίσεται</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίου</span>, receberá isso do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:8</a> (PSI 438, 11 [III a.C.] <span class=\"greek\">κεκόμισμαι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">Φανίου</span> <span class=\"greek\">ἐπιστολήν</span>, recebi uma carta de Fânias). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπαγγελίαν</span>, a promessa (isto é, aquilo que foi prometido), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:36</a>; 11:13, variante de leitura, 39. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">σωτηρίαν</span> <span class=\"greek\">ψυχῶν</span>, alcançar como resultado da fé a salvação das almas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:9</a> (em contraste com 4:17).—DELG s.v. <span class=\"greek\">κομέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόμπος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόμπος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e outros): autopromoção ostensiva, jactância, arrogância (assim autores trágicos, Hdt.; Esth 8:12d; 3 Macc 6:5; Philo, Congr. Erud. Gr. 61; Jos., Bell. 6, 260; Just., A II, 9, 1), 1 Cl 16:2.—Adjetivo <span class=\"greek\">κομπός</span>, jactancioso, AcPl Ha 2, 22.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κομφέκτωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κομφέκτωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (empréstimo do latim confector; Suetonius, Octav. 43, Nero 12. A forma grega encontra-se em Acta S. Meletii 39): executor, encarregado de dar o golpe de misericórdia a gladiadores feridos, MPol 16:1 (veja Lghtf. ad loc.).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κομψότερον</h1><div class=\"entry-meta\"><span>advérbio comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κομψότερον</span>: advérbio do comparativo de <span class=\"greek\">κομψός</span> (a palavra ocorre desde Eur. e outros; o comparativo, em Pla., Crat. 429d; POxy 935, 5 [III d.C.]): melhor, a respeito de pessoas doentes; <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span>, começar a melhorar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:52</a> (<span class=\"greek\">κομψῶς</span> <span class=\"greek\">ἔχειν</span> neste sentido, em Epict. 3, 10, 13; PParis 18, 3; PTebt 414, 10. Esse emprego desenvolve-se como sentido transferido de <span class=\"greek\">κομψός</span>, ‘agradável’ [compare ‘Fulano está indo bem’]. Sobre o comparativo, compare POxy 935, 5 <span class=\"greek\">θεῶν</span> <span class=\"greek\">συνλαμβανόντων</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀδελφὴ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κομψότερον</span> <span class=\"greek\">ἐτράπη</span>, com o auxílio dos deuses, minha irmã começou a melhorar; FBilabel, Badische Papyri 1923 no. 34, 4 [I d.C.] <span class=\"greek\">κομψότερον</span> <span class=\"greek\">ἔσχεν</span>).—DELG s.v. <span class=\"greek\">κομψός</span>. M-M. s.v. <span class=\"greek\">κομψῶς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κονιάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κονιάω</span>: particípio perfeito passivo <span class=\"greek\">κεκονιαμένος</span> (Aesop, Fab. 121 P. = 193 H. <span class=\"greek\">ἐν</span> <span class=\"greek\">κεκονιαμένῳ</span> <span class=\"greek\">οἴκῳ</span>, em casa caiada) (<span class=\"greek\">κόνις</span>, ‘poeira, reboco’; Demosth. e outros; Michel 594, 96; SIG 695, 88. Passiva em CIG I 1625, 16; Dt 27:2, 4; Pr 21:9): caiar, revestir de cal; <span class=\"greek\">τοῖχος</span> <span class=\"greek\">κ</span>., parede caiada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:3</a> (veja <span class=\"greek\">τοῖχος</span>). <span class=\"greek\">τάφοι</span> <span class=\"greek\">κ</span>., sepulcros caiados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:27</a> (BMcCane, Is a Corpse Contagious? Early Jewish and Christian Attitudes toward the Dead: SBLSP ’92, 378–88), com sátira implícita: os fariseus são, sem o perceber, fonte de contaminação. GNaass 284, 153 (compare Aesop, acima).—KRengstorf, Rabb. Texte, 1. Reihe III ’33ff, p. 34f.—DELG s.v. <span class=\"greek\">κόνις</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κονιορτός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κονιορτός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">κόνις</span>, ‘poeira’, + <span class=\"greek\">ὄρνυμι</span>, ‘levantar’; desde Hdt.; Mitt-Wilck. I/2, 198, 16 [III a.C.]; LXX; TestSol 7:2f; Philo, Exs. 133; Jos., Ant. 3, 193; Tat. 30, 1): poeira, pó; <span class=\"greek\">ἐκτινάσσειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span>, sacudir a poeira dos pés (compare Heraclit. Sto. 10 p. 17, 8, após Il. 2, 150 <span class=\"greek\">ποδῶν</span> … <span class=\"greek\">κονίη</span>; Na 1:3 <span class=\"greek\">κ</span>. <span class=\"greek\">ποδῶν</span> <span class=\"greek\">αὐτοῦ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:14</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:5</a>; 10:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.51\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:51</a> (veja <span class=\"greek\">ἐκτινάσσω</span> 1). A respeito de uma multidão desordeira: <span class=\"greek\">κονιορτὸν</span> <span class=\"greek\">βάλλειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀέρα</span>, lançar poeira ao ar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:23</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐγείρειν</span>, levantar poeira (compare Appian, Mithrid. 87 §396 <span class=\"greek\">κονιορτὸς</span> <span class=\"greek\">ἠγείρετο</span>; Jos., Bell. 5, 471; veja também <span class=\"greek\">ἐγείρω</span> 10), Hv 4, 1, 5b.—Nuvem de poeira (Aristodem. [IV d.C.]: 104 Fgm. 1, 8 Jac.): <span class=\"greek\">κ</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανόν</span>, nuvem de poeira que se eleva, por assim dizer, até o céu, 4, 1, 5a (Quint. Smyrn. 2, 469f <span class=\"greek\">κόνις</span> <span class=\"greek\">ἄχρις</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">οὐρανόν</span>). <span class=\"greek\">γινομένου</span> <span class=\"greek\">μείζονος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μείζονος</span> <span class=\"greek\">κονιορτοῦ</span>, quando a nuvem de poeira cresceu cada vez mais, 4, 1, 6.—B. 19. DELG s.v. <span class=\"greek\">κόνις</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοπάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοπάζω</span> (veja <span class=\"greek\">κόπος</span>): 1º aoristo <span class=\"greek\">ἐκόπασα</span>; perfeito <span class=\"greek\">κεκόπακα</span>, LXX (Hdt. e outros; LXX, e a partir de Num 17:13 em Philo, Somn. 2, 235, a partir de Gen 8:8 em SibOr 1, 246; AWilhelm, SymbOsl, Suppl. 13, ’50, 32, epigrama grego: <span class=\"greek\">ἡ</span> <span class=\"greek\">μακρὴ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">δυσπλοί̈η</span> <span class=\"greek\">κοπάσει</span>, a longa e difícil travessia marítima que enfrentei logo amainará): diminuir, parar, repousar, cessar; <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνεμος</span> <span class=\"greek\">ἐκόπασεν</span>, o vento amainou (assim Hdt. 7, 191; compare Aelian em Suda [Anz 316]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:39</a>; 6:51.—DELG s.v. <span class=\"greek\">κόπτω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοπετός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοπετός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Eupolis Com. [V a.C.], Fgm. 347; Dionys. Hal. 11, 31; Plut., Fab. 17, 7; Kaibel 345, 4; LXX; TestJob 40:13; 52:1 [códice V]; SibOr 5, 193; Joseph.; Mel., P. 18, 121; 28, 194; Ath. 14, 2): luto, lamentação. Conforme o costume em muitas regiões do mundo mediterrâneo, era acompanhado por batidas no peito (prática censurada por Plut., Mor. 609b; veja <span class=\"greek\">κόπτω</span> 2): <span class=\"greek\">ἐποίησαν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μέγαν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῷ</span>, fizeram grande lamentação por ele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:2</a> (Mi 1:8 <span class=\"greek\">κ</span>. <span class=\"greek\">ποιεῖσθαι</span> [MWilcox, The Semitisms of Ac, ’65, 136f]; Zech 12:10 <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>; compare Jer 9:9; Jos., Bell. 2, 6). <span class=\"greek\">δύο</span> <span class=\"greek\">κοπετοὺς</span> <span class=\"greek\">ἐκόπτετο</span>, (Ana) lamentava-se duplamente (a saber, pela viuvez e pela falta de filhos), GJs 2:1.—DELG s.v. <span class=\"greek\">κόπτω</span> A6. Frisk s.v. <span class=\"greek\">κόπτω</span> 8 (via <span class=\"greek\">κόπος</span>?). M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοπή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κόπτω</span>; Strabo e outros; papiros; JosAs 23:7, códice A [<span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ῥομφαίας</span>, ‘punho da espada’]): corte, mortandade (Josh 10:20; Jdth 15:7); <span class=\"greek\">ὑποστρέφειν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλέων</span>, regressar da derrota dos reis (isto é, depois de derrotá-los), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:1</a> (Gen 14:17).—DELG s.v. <span class=\"greek\">κόπτω</span> A2. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοπιάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοπιάω</span>: futuro <span class=\"greek\">κοπιάσω</span>, LXX; 1º aoristo <span class=\"greek\">ἐκοπίασα</span>; perfeito <span class=\"greek\">κεκοπίακα</span>; 2ª pessoa do singular <span class=\"greek\">κεκοπίακες</span> ou -<span class=\"greek\">κας</span> (variante de leitura; veja B-D-F §83, 2; Mlt-H. 221); aoristo passivo, 3ª pessoa do singular, <span class=\"greek\">ἐκοπιάθη</span> (de <span class=\"greek\">κόπτω</span> por intermédio de <span class=\"greek\">κόπος</span>; TestAbr B 2 p. 107, 1 [Stone p. 62]) (Aristoph. e outros; Hippocr.; Epicurus 59, 3 Us.; inscrições, papiros, LXX, En; TestJob 24:2; ApcSed 4:3; ApcMos 24; Philo, Joseph.).</p>\n<p class=\"entry-text\">① Ficar cansado, fatigado (Aristoph. e outros; Sir 16:27; 1 Macc 10:81; 4 Macc 9:12; Jos., Bell. 6, 142), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:3</a> (o perfeito expressa aqui a ideia de que a congregação de Éfeso não se cansou a ponto de ‘desistir’). Com <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, de alguma coisa: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοιπορίας</span>, da viagem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:6</a> (compare Jos., Ant. 2, 321 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοιπορίας</span> <span class=\"greek\">κεκοπωμένοι</span>; Is 40:31). <span class=\"greek\">οἱ</span> <span class=\"greek\">κοπιῶντες</span>, os que estão cansados (Diocles 142 p. 186, 28; compare 1QH 8:36), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:28</a> (veja <span class=\"greek\">φορτίζω</span>).</p>\n<p class=\"entry-text\">② Empenhar-se física, mental ou espiritualmente; trabalhar arduamente, labutar, esforçar-se, lutar (Vett. Val. 266, 6; Syntipas p. 107, 15; POslo 160, 1; Philo, Mut. Nom. 254, Cher. 41), absolutamente (Aesop, Fab. 391 P.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:5</a>; 12:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:38b</a>; 21:6, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:12</a>; 16:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:6</a>. Com <span class=\"greek\">τὶ</span>, trabalhar por alguma coisa (En 103:9 <span class=\"greek\">κόπους</span> <span class=\"greek\">κ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:38a</a>. <span class=\"greek\">πολλά</span>, trabalhar muito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:6</a>, 12b; Hs 5, 6, 2; 2 Cl 7:1. <span class=\"greek\">περισσότερον</span>, ainda mais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:10</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, trabalhar em alguma coisa (Sir 6:19): <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διδασκαλίᾳ</span>, empenhar-se na pregação e no ensino, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:17</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">λόγου</span>, trabalhar por meio da palavra, B 19:10. Quanto à esfera em que se dá o trabalho: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, entre vós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:12</a>. Quanto à maneira: <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, no Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:12ab</a>; <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> <span class=\"greek\">κ</span>., trabalhar arduamente por alguém, v. 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:11</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span>, para isto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:10</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">κοπιῶ</span>, é por isto que me esforço, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:29</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">κενόν</span>, labutar em vão (compare Is 49:4 <span class=\"greek\">κενῶς</span> <span class=\"greek\">ἐκοπίασα</span>; 65:23 <span class=\"greek\">κοπιάσουσιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κενόν</span>; TestJob 24:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:16</a>. Também <span class=\"greek\">εἰς</span> <span class=\"greek\">μάτην</span> (Ps 126:1), Hs 9, 4, 8.—B. 312. DELG s.v. <span class=\"greek\">κόπτω</span> A1. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόπος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόπος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>.</p>\n<p class=\"entry-text\">① Estado de desconforto ou aflição; perturbação, dificuldade, sentido figurado de <span class=\"greek\">κόπος</span> = ‘espancamento’ (veja <span class=\"greek\">κόπτω</span>; autores trágicos; papiros; Ps 106:12; Sir 22:13; 1 Macc 10:15; ParJer 5:6; Jos., Ant. 2, 257; Just., D. 68, 2): <span class=\"greek\">κόπους</span> (<span class=\"greek\">κόπον</span>) <span class=\"greek\">παρέχειν</span> <span class=\"greek\">τινί</span>, causar dificuldades a alguém, incomodá-lo (<span class=\"greek\">κόπους</span> <span class=\"greek\">παρέχειν</span> <span class=\"greek\">τινί</span>, PTebt 21, 10 [115 a.C.]; BGU 844, 12; PGissUniv 27, 13f [III d.C.]; PGM 14b, 4f; <span class=\"greek\">κόπον</span> <span class=\"greek\">παρ</span>. <span class=\"greek\">τινί</span>, Sir 29:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:7</a>; 18:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:17</a>; Hv 3, 3, 2; AcPlCor 2:34. <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">κόπους</span> <span class=\"greek\">ἠντληκώς</span>, depois de ter suportado muitas dificuldades, Hs 5, 6, 2a (compare Did.. Gen. 105, 9). Juntamente com outros termos relativos a situações de provação (FDanker, 2 Cor [Augsburg Comm.], ’89, 85–91; 180–86), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:5</a> e 11:23; sobre 10:15, veja 2 abaixo.</p>\n<p class=\"entry-text\">② Envolver-se em atividade penosa; trabalho, labor, esforço (Eur., Aristoph.; SIG 761, 6 [I a.C.]; PAmh 133, 11; POxy 1482, 6; LXX; En; TestIss 3:5; Apc4Esdr Fgm. a; ApcSed 14:2; Jos., Ant. 3, 25; 8, 244; Iren.1, 13, 5 [Harv I 122, 3]; Did., Gen. 104, 7). No singular, <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀγάπης</span>, trabalho de amor, isto é, serviço amoroso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:3</a>. Com <span class=\"greek\">ἔργα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:2</a>; com <span class=\"greek\">ἱδρώς</span>, B 10:4; com <span class=\"greek\">μόχθος</span> (veja a entrada correspondente), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:8</a>; Hs 5, 6, 2b. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">κενός</span>, vosso trabalho não é vão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.58\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:58</a>. <span class=\"greek\">μήπως</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κενὸν</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span>, para que nosso trabalho não seja infrutífero, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5</a>. Figuradamente, sobre o trabalho da colheita: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τινὸς</span> <span class=\"greek\">εἰσέρχεσθαι</span>, entrar no trabalho de outra pessoa, isto é, colher o fruto do trabalho alheio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:38</a>; <span class=\"greek\">τὸν</span> <span class=\"greek\">μισθὸν</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., receber o pagamento segundo o trabalho realizado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:8</a>. <span class=\"greek\">ὅπου</span> <span class=\"greek\">πλείων</span> <span class=\"greek\">κ</span>., <span class=\"greek\">πολὺ</span> <span class=\"greek\">κέρδος</span>, quanto maior o trabalho, maior o ganho, IPol 1:3.—No plural, para atos individuais de trabalho (En 7:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:15</a> (6:5 e 11:23 parecem ajustar-se melhor ao sentido 1 acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:13</a>. Também o abstrato pelo concreto: recompensa pelo trabalho (Sir 14:15), Hm 2:4; Hs 9, 24, 2f.—AvHarnack, <span class=\"greek\">Κόπος</span> (<span class=\"greek\">κοπιᾶν</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">κοπιῶντες</span>) im frühchristl. Sprachgebr.: ZNW 27, 1928, 1–10; HKuist, Bibl. Review 16, ’31, 245–49. B. 540.—DELG s.v. <span class=\"greek\">κόπτω</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοπρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοπρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja os três verbetes seguintes; Strattis Com. [V a.C.], Fgm. 43; Strabo 7, 5, 7; 16, 4, 26; Epict. 2, 4, 5; M. Ant. 8, 51, 2; POxy 37 I, 6 [49 d.C.]; PRyl 162, 17; LXX, TestJob.—UWilcken, APF 2, 1903, 311f): monte de esterco, esterqueira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:8</a>, variante de leitura; 14:35.—DELG s.v. <span class=\"greek\">κόπρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόπριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόπριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja o verbete precedente e os dois seguintes; Heraclitus 96; Epict. 2, 4, 5; Plut., Pomp. 48, 2; OGI 483, 81 [II a.C.]; PFay 110, 5; 10; POxy 502, 32 <span class=\"greek\">καθαρὰ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κοπρίων</span>, livre de sujeira; Jer 32:33; Sir 22:2).</p>\n<p class=\"entry-text\">① Esterco, estrume: <span class=\"greek\">κόπρια</span> <span class=\"greek\">βάλλειν</span>, colocar esterco, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:8</a> (Theophr., Caus. Pl. 3, 9, 5 <span class=\"greek\">παραβάλλειν</span> <span class=\"greek\">κόπρον</span>).</p>\n<p class=\"entry-text\">② Imundície, sujeira, sentido transferido de 1 (BGU I, 15, 50 [I a.C.]): <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αἴρειν</span>, remover a sujeira (PGM 4, 1441), Hs 9, 10, 3.—DELG s.v. <span class=\"greek\">κόπρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόπρον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόπρον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja os dois verbetes precedentes e o seguinte; Galen XII 290 K.—Para a LXX, <span class=\"greek\">ἡ</span> <span class=\"greek\">κόπρος</span> [veja a entrada seguinte] é seguramente correta sempre que se possa estabelecer o gênero. Mas existe também o acusativo <span class=\"greek\">κόπρον</span>, que, sem artigo, pode ser feminino ou neutro [Is 30:22; 36:12, tendo esta última forma <span class=\"greek\">τήν</span> como variante de leitura]; TestBenj 8:3; ApcMos 6; e, da mesma maneira, o genitivo <span class=\"greek\">κόπρου</span> [4 Km 6:25; Ezk 4:12; Jos., Ant. 9, 62; PGM 7, 485]): Hs 9, 10, 3, se a restauração <span class=\"greek\">τὰ</span> <span class=\"greek\">κό</span>[<span class=\"greek\">πρα</span>] em FXFunk2 1901 estiver correta, e talvez <span class=\"greek\">κόπρον</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:8</a>, variante de leitura. Esta última forma, porém, provavelmente pertence à entrada seguinte.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόπρος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόπρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (veja os três verbetes precedentes; Hom. e outros; Diod S 4, 13, 3; Dio Chrys. 13 [7], 16; 15 [32], 87; inscrições, papiros, LXX; Tat. 3, 1 [veja <span class=\"greek\">κόπρον</span>]): esterco, estrume. Como esta forma está incomparavelmente melhor atestada do que a neutra da entrada precedente, é quase certo que os casos duvidosos ali mencionados pertençam a esta palavra.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόπτω</span>: imperfeito <span class=\"greek\">ἔκοπτον</span>; 1º aoristo <span class=\"greek\">ἔκοψα</span>, na voz média <span class=\"greek\">ἐκοψάμην</span>; futuro médio <span class=\"greek\">κόψομαι</span>. Na passiva: 2º aoristo <span class=\"greek\">ἐκόπην</span> (Hs 8, 1, 4); particípio perfeito <span class=\"greek\">κεκομμένος</span> (Hs 8, 1, 4) (desde Hom.; inscrições, papiros, LXX; TestSol; ApcSed 7:10; Ar. 8, 2; Just.; Mel., P. 19, 128; 29, 201).</p>\n<p class=\"entry-text\">① Cortar, cortar fora, na voz ativa (Jos., Vi. 171; Just., D. 86, 6); com <span class=\"greek\">τὶ</span> <span class=\"greek\">ἀπό</span> (ou <span class=\"greek\">ἔκ</span>) <span class=\"greek\">τινος</span>, alguma coisa de outra coisa (Quint. Smyrn. 11, 71 <span class=\"greek\">κ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>): <span class=\"greek\">κλάδους</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δένδρων</span>, ramos das árvores, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:8</a>. <span class=\"greek\">κλάδους</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰτέας</span>, ramos do salgueiro, Hs 8, 1, 2; compare 4; 8, 3, 1; 8, 4, 4f. <span class=\"greek\">στιβάδας</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγρῶν</span>, ramos com folhas retirados dos campos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:8</a> (compare X., Hell. 5, 2, 43; POslo 17, 7 [136 d.C.]; Is 44:14 <span class=\"greek\">ξύλον</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δρυμοῦ</span>; 2 Ch 2:15; SibOr 3, 651).—Figuradamente: <span class=\"greek\">πολὺ</span> <span class=\"greek\">κόψετε</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προτέρων</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἁμαρτιῶν</span>, eliminareis muitos dos vossos antigos pecados, Hs 6, 1, 4.</p>\n<p class=\"entry-text\">② Bater no próprio peito como manifestação de luto, na voz média (Aeschyl., Pers. 683; compare Cho. 22–31; Pla., Phd. 60b; LXX; Jos., Ant. 7, 41; veja <span class=\"greek\">κοπετός</span>): <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">στήθνη</span>, bater no peito (PGM 36, 139), GPt 8:28. Depois, em uso absoluto: lamentar (profundamente) (Lucian, De Sacrific. 15; 3 Km 13:29, variante de leitura; Zech 7:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:30</a>; GPt 7:25; (com <span class=\"greek\">θρηνεῖν</span>, veja as acepções 2 e 3 dessa entrada e Jos., Ant. 8, 273), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:27</a>; (com <span class=\"greek\">κλαίειν</span>, veja 1 dessa entrada), GPt 12:52, 54; GJs 17:2. Com acusativo cognato: <span class=\"greek\">δύο</span> <span class=\"greek\">κοπετοὺς</span> <span class=\"greek\">ἐκόπτετο</span>, lamentava-se duplamente, GJs 2:1. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σάκκου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σποδοῦ</span>, lamentar-se em pano de saco e cinzas, B 7:5 (o emprego incomum de <span class=\"greek\">ἐπί</span> provavelmente se explica porque a pessoa enlutada se sentava sobre cinzas; compare 3:2). Seguido de acusativo, lamentar alguém (Aristoph., Lys. 396; Pla., Rep. 10, 619c; Anth. Pal. 11, 135, 1; Gen 23:2; 1 Km 25:1 e outras passagens; Jos., Ant. 13, 399), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:52</a>; compare 23:27; GJs 24:3. <span class=\"greek\">τὴν</span> <span class=\"greek\">χηροσύνην</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀτεκνίαν</span>, a viuvez e a ausência de filhos, 2:1. Também <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, lamentar por alguém (2 Km 1:12; 11:26, variante de leitura), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:7</a>; 18:9.—EMartino, Morte e pianto rituale nel mondo antico, ’58, 217–20 (bibliografia). Os temas principais da lamentação em Hom., Il. 18, 22–64.—B. 553; 557. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόραξ, ακος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόραξ</span>, <span class=\"greek\">ακος</span>, <span class=\"greek\">ὁ</span> (Hom. e outros; PMagd 21, 5; LXX; PsSol 4:20; TestJud 21:8; ParJer 7:8; Jos., Ant. 1, 91 e outras passagens; Tat. 1, 3): corvo, gralha, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:24</a>. Os judeus eram proibidos de comê-lo, B 10:1, 4 (Lev 11:15; Dt 14:14).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0207-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοράσιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοράσιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Pla. em Diog. L. 3, 33; Philippides Com. [IV/III a.C.] 36; Epict. 2, 1, 28; 3, 2, 8; 4, 10, 33; Anth. Pal. 9, 39, 1; IG VII, 3325; PStras 79, 2 [16/15 a.C.]; BGU 887, 9; 913, 7; LXX. Veja Lob. sobre Phryn. 73–75; PKretschmer, D. Entstehung der <span class=\"greek\">Κοινή</span> 1900, 17; FSolmsen, RhM 59, 1904, 503f): diminutivo de <span class=\"greek\">κόρη</span>; menina (segundo Wellhausen, tradução do aramaico <span class=\"hebrew\" dir=\"rtl\">רְבִיָתא</span>, em lugar do qual o mais elegante <span class=\"hebrew\" dir=\"rtl\">טְלִיתָא</span> foi inserido como correção: veja Wlh., EKlostermann ad loc.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:41</a> (sobre <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. como vocativo, veja B-D-F §147, 3; Rob. 461).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:24f</a>; 14:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:42</a>; 6:22, 28.—DELG s.v. 2 <span class=\"greek\">κόρος</span>. M-M.</p></section></article>"};
